(() => {
  const out = {};
  const details = document.querySelector('.sidebar ul, .task-details, .sidebar');
  out.sidebarText = details ? details.innerText : null;
  const desc = document.querySelector('.accordion-section article, #description article, .task-description');
  out.desc = desc ? desc.innerText : null;
  const comments = document.querySelector('#comments, .comments');
  out.comments = comments ? comments.innerText : null;
  out.url = location.href;
  return out;
})()

(() => {
  const items = [...document.querySelectorAll('li')].filter(li => /Due date:|Column:|Status:|Assignee:/.test(li.innerText)).map(li => li.innerText.trim());
  const title = document.querySelector('h2') ? [...document.querySelectorAll('h2')].map(h=>h.innerText) : null;
  return {items, headings: [...document.querySelectorAll('h2')].map(h=>h.innerText), cardNumber: document.querySelector('.task-number, #task-number') ? document.querySelector('#task-number').innerText : null};
})()
